// Build the weekly Road to 30 recap from Notion and save it as a Threads draft
const BIRTHDAY_30 = 'YYYY-MM-DD';   // set this: the day you turn 30
const START = 'YYYY-MM-DD';         // set this: one year before that day
const POSTS_DB = '41c735e40e258186845fd5323669362c';

const sessions = $('Sessions this week').first().json.results || [];
const goals = $('All goals').first().json.results || [];
const plain = x => (x?.rich_text || x?.title || []).map(t => t.plain_text).join('');
const fmt = m => { m = Math.round(m); const h = Math.floor(m / 60), r = m % 60; return h ? (r ? `${h}h ${r}m` : `${h}h`) : `${r}m`; };

let total = 0; const bySubj = {}; const days = new Set();
for (const s of sessions) {
  const p = s.properties; const min = p['Minutes']?.number || 0; total += min;
  const subj = p['Subject']?.select?.name || 'Other'; bySubj[subj] = (bySubj[subj] || 0) + min;
  const d = p['Date']?.date?.start; if (d) days.add(d.slice(0, 10));
}
let stepsDone = 0, stepsTotal = 0;
for (const g of goals) { stepsDone += g.properties['Steps done']?.number || 0; stepsTotal += g.properties['Steps total']?.number || 0; }

const now = new Date();
const week = Math.floor((now - new Date(START + 'T00:00:00')) / (7 * 864e5)) + 1;
const daysLeft = Math.ceil((new Date(BIRTHDAY_30 + 'T00:00:00') - now) / 864e5);
const top = Object.entries(bySubj).sort((a, b) => b[1] - a[1]).slice(0, 3).map(([k, v]) => `${k} ${fmt(v)}`).join(' · ');

const text = total
  ? `Road to 30 · week ${week}\n\n📚 ${fmt(total)} of study this week, on ${days.size} days\n${top}\n✅ ${stepsDone}/${stepsTotal} goal steps done so far\n⏳ ${daysLeft} days to 30. Still growing.\n\n#RoadTo30 #DataEngineering`
  : `Road to 30 · week ${week}\n\nA quiet week for study. Resetting and starting again on Monday.\n⏳ ${daysLeft} days to 30.\n\n#RoadTo30`;

return [{ json: { page: {
  parent: { database_id: POSTS_DB },
  properties: {
    'Post': { title: [{ text: { content: `Weekly recap · week ${week}` } }] },
    'Text': { rich_text: [{ text: { content: text.slice(0, 500) } }] },
    'Status': { select: { name: 'Draft' } },
    'Type': { select: { name: 'Weekly recap' } },
  },
} } }];
